/**
 * Exit gate for Phase 0: the solver must match a published solver's dope tables within 1%
 * out to 1,000 m (1,200 m for the .338). Reference tables come from py-ballisticcalc 3.1.0,
 * generated by reference/generate.py.
 */
import { describe, expect, it } from 'vitest';
import { pointAtRange, relativeToLos, simulate, solveZero } from '../src/index.ts';
import { reference, setupFor, type RefScenario } from './reference.ts';

const REL_TOL = 0.01; // 1%
const ABS_FLOOR = 0.005; // 5 mm, so near-zero values (at the zero range) aren't judged by a % of nothing

function expectClose(actual: number, expected: number, label: string): void {
  const tol = Math.max(REL_TOL * Math.abs(expected), ABS_FLOOR);
  if (Math.abs(actual - expected) > tol) {
    throw new Error(`${label}: got ${actual.toFixed(4)}, reference ${expected.toFixed(4)} (tolerance ±${tol.toFixed(4)})`);
  }
}

function fly(s: RefScenario, zeroElevation: number) {
  const { shot, env } = setupFor(s);
  return simulate({ ...shot, zeroElevation }, env, {
    maxRange: s.rows[s.rows.length - 1]!.range,
    effects: { spinDrift: s.spinDrift, coriolis: s.coriolis !== null },
  });
}

describe(`dope tables vs ${reference.generator}`, () => {
  for (const s of reference.scenarios) {
    describe(s.name, () => {
      // Use the reference's own zero so each table checks the flight, not the zeroing.
      const traj = fly(s, s.zeroElevationMrad / 1000);
      for (const row of s.rows) {
        it(`${row.range} m: drop, drift, velocity and time of flight within 1%`, () => {
          const p = pointAtRange(traj, row.range);
          expect(p).toBeDefined();
          const rel = relativeToLos(p!, 0);
          expectClose(rel.height, row.height, 'height vs line of sight (m)');
          expectClose(rel.lateral, row.windage, 'windage (m)');
          expect(Math.abs(p!.speed - row.velocity) / row.velocity).toBeLessThan(0.005);
          expect(Math.abs(p!.t - row.time) / row.time).toBeLessThan(0.005);
        });
      }
    });
  }
});

describe('zeroing matches the reference', () => {
  for (const s of reference.scenarios.filter((x) => x.coriolis === null)) {
    it(s.name, () => {
      const { shot, env } = setupFor(s);
      const zero = solveZero(shot, env, reference.zeroRangeM);
      expect(Math.abs(zero * 1000 - s.zeroElevationMrad) / s.zeroElevationMrad).toBeLessThan(0.001);
    });
  }
});

describe('Coriolis and Eötvös effect matches the reference', () => {
  const base = reference.scenarios.find((s) => s.load === '338lm' && s.atmosphere === 'icao' && !s.spinDrift && !s.coriolis)!;
  for (const s of reference.scenarios.filter((x) => x.coriolis !== null)) {
    it(s.name, () => {
      // Compare the Coriolis contribution itself, (with − without), on the same zero on both sides.
      expect(s.zeroElevationMrad).toBe(base.zeroElevationMrad);
      const zero = s.zeroElevationMrad / 1000;
      const withC = fly(s, zero);
      const withoutC = fly(base, zero);
      for (const row of s.rows.filter((r) => r.range >= 300)) {
        const baseRow = base.rows.find((r) => r.range === row.range)!;
        const a = relativeToLos(pointAtRange(withC, row.range)!, 0);
        const b = relativeToLos(pointAtRange(withoutC, row.range)!, 0);
        const refDeltaH = row.height - baseRow.height;
        const refDeltaW = row.windage - baseRow.windage;
        expect(Math.abs(a.height - b.height - refDeltaH)).toBeLessThan(Math.max(0.03 * Math.abs(refDeltaH), 0.0005));
        expect(Math.abs(a.lateral - b.lateral - refDeltaW)).toBeLessThan(Math.max(0.03 * Math.abs(refDeltaW), 0.0005));
      }
    });
  }
});
